let catalogLoaded=false, catalogRunning=false, catalogFailure=false, catalogParts=[], loadedParts=new Set(), currentSummaryKey=null;
const summaryRequests=new Map();
function prepareControls(){
 if(!$('source-filter')){
  const label=document.createElement('label');label.id='source-filter-label';label.innerHTML='<span data-t="catalogSource">منبع</span><select id="source-filter"><option value="" data-t="allSources">همهٔ منابع</option><option value="ganjoor">Ganjoor</option><option value="gutenberg">Project Gutenberg</option></select>';
  document.querySelector('.filters').append(label);
 }
 if(!$('load-panel')){
  const panel=document.createElement('div');panel.id='load-panel';panel.className='load-panel';panel.innerHTML='<span id="load-message"></span> <button id="catalog-retry" class="text-button" hidden></button> <a id="catalog-static-link" href="/ketavilo/catalog.html"></a>';
  $('grid').before(panel);
 }
 if(!$('availability')){const label=document.createElement('label');label.innerHTML='<span data-t="availability">دسترسی</span><select id="availability"><option value="readable" data-t="readableOnly">قابل مطالعه در سایت</option><option value="" data-t="allFormats">همهٔ قالب‌ها</option><option value="pdf" data-t="pdfOnly">فقط PDF آماده · ۱۳ کتاب</option></select>';document.querySelector('.filters').append(label);$('availability').value=availability;$('availability').onchange=e=>{availability=e.target.value;limit=25;buildCategories();render()}}
 $('source-filter').value=sourceFilter;$('search').value=term;$('sort').value=sort;
 document.querySelectorAll('dialog').forEach(dialog=>{
  if(typeof dialog.showModal==='function')return;
  if(typeof dialog.open!=='boolean')Object.defineProperty(dialog,'open',{configurable:true,get(){return this.hasAttribute('open')},set(value){if(value)this.setAttribute('open','');else this.removeAttribute('open')}});
  dialog.showModal=function(){this.setAttribute('open','');this.classList.add('fallback-dialog');document.body.classList.add('dialog-open')};
  dialog.close=function(){this.removeAttribute('open');this.classList.remove('fallback-dialog');document.body.classList.remove('dialog-open');this.dispatchEvent(new Event('close'))};
 });
}
async function fetchData(path,timeout=15000,kind='json'){
 const controller=typeof AbortController==='function'?new AbortController():null;
 let timer;const request=fetch('/ketavilo/'+path,controller?{signal:controller.signal}:{}).then(response=>{if(!response.ok)throw new Error('HTTP '+response.status);return kind==='text'?response.text():response.json()});
 try{return await Promise.race([request,new Promise((_,reject)=>{timer=setTimeout(()=>{if(controller)controller.abort();reject(new Error('Request timed out'))},timeout)})])}finally{clearTimeout(timer)}
}
function addBooks(rows){
 for(const b of rows){if(byId.has(b[0]))continue;b.search=norm(b[1]+' '+b[2]);books.push(b);byId.set(b[0],b)}
}
function loadingState(){
 const panel=$('load-panel');if(!panel)return;
 const completeSource=view==='library'&&sourceFilter==='ganjoor';
 panel.hidden=view==='summaries'||catalogLoaded||completeSource;
 $('load-message').textContent=t(catalogFailure?'partialError':'partialLoading')+' '+n(loadedParts.size)+' / '+n(catalogParts.length);
 $('catalog-retry').disabled=catalogRunning;$('catalog-retry').hidden=!catalogFailure;$('catalog-retry').textContent=t('retryCatalog');
 $('catalog-static-link').textContent=t('readyCatalog');$('catalog-static-link').href=category>=0?'/ketavilo/category-'+category+'.html':'/ketavilo/catalog.html';
}
async function loadCatalog(){
 if(catalogRunning||catalogLoaded||!catalogParts.length)return;
 catalogRunning=true;catalogFailure=false;loadingState();
 const pending=catalogParts.filter(path=>!loadedParts.has(path));let next=0;
 async function worker(){
  while(next<pending.length&&!catalogFailure){
   const path=pending[next++];
   try{
    if(navigator.onLine===false)throw new Error('Offline');
    const rows=await fetchData(path);
    if(!Array.isArray(rows))throw new Error('Invalid catalog part');
    for(let i=0;i<rows.length;i+=500){addBooks(rows.slice(i,i+500));await new Promise(resolve=>setTimeout(resolve,0))}
    loadedParts.add(path);catalogLoaded=loadedParts.size===catalogParts.length;
    if(view!=='summaries'&&sourceFilter!=='ganjoor'&&(catalogLoaded||term||view==='saved'||category>=0&&loadedParts.size%4===0))render();loadingState();
   }catch(error){catalogFailure=true;loadingState()}
  }
 }
 try{await Promise.all([worker(),worker()])}finally{catalogRunning=false;loadingState()}
}
async function fetchSummary(summary){
 if(!summaryRequests.has(summary.chunk)){
  const promise=fetchData(summary.chunk).then(rows=>{
   for(const item of rows){const existing=summaries.find(x=>x.key===item.key);if(existing)Object.assign(existing,item)}
  }).catch(error=>{summaryRequests.delete(summary.chunk);throw error});
  summaryRequests.set(summary.chunk,promise);
 }
 await summaryRequests.get(summary.chunk);
}
async function openSourcedSummary(summary){
 currentSummaryKey=summary.key;
 const lang=summary.content[language]?language:'en';let c=summary.content[lang];
 if(!c.text){
  $('summary-body').innerHTML=`<h2 dir="auto">${esc(summary.title[language]||summary.title.en)}</h2><p role="status">${t('summaryLoading')}</p>`;
  if(!$('summary-dialog').open)$('summary-dialog').showModal();
  try{await fetchSummary(summary)}catch(error){
   if(currentSummaryKey===summary.key&&$('summary-dialog').open)$('summary-body').innerHTML=`<h2 dir="auto">${esc(summary.title[language]||summary.title.en)}</h2><p role="status">${t('summaryLoadError')}</p><button class="primary" data-summary="${esc(summary.key)}">${t('retryCatalog')}</button><p><a href="/ketavilo/summaries.html">${t('readyCatalog')}</a></p>`;
   return;
  }
  if(currentSummaryKey!==summary.key||!$('summary-dialog').open)return;c=summary.content[lang];
 }
 $('summary-body').innerHTML=`<h2 dir="auto">${esc(summary.title[language]||summary.title.en)}</h2><p class="author" dir="auto">${esc(summary.author)}</p><p>${esc(languageName(lang))} · ${t('sourcedSummary')}</p>${lang!==language?`<p class="notice">${t('fallbackSummary')}</p>`:''}<p class="source-note">${t('spoilers')}</p><div class="source-summary" lang="${lang}" dir="${lang==='en'?'ltr':'rtl'}">${c.text.split(/\n\s*\n/).map(p=>`<p>${esc(p)}</p>`).join('')}</div><div class="source-note"><p>${t('sourceCredit')}</p><a href="${esc(c.source)}" target="_blank" rel="noopener noreferrer">Wikipedia: ${esc(c.sourceTitle)}</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a></div>`;
 if(!$('summary-dialog').open)$('summary-dialog').showModal();
}
async function start(){
 try{
  const inline=$('library-bootstrap');const data=inline?JSON.parse(inline.textContent):await fetchData('bootstrap-v9.json');
  meta=JSON.parse(JSON.stringify(data.meta));sourceBooks=data.sourceBooks;summaries=data.summaries;localIds=new Set(data.localIds);catalogParts=data.parts;
  addBooks(data.books);let rank=-1000;
  for(const [key,source] of Object.entries(sourceBooks)){
   const id=Number(key);addBooks([[id,source.title,source.author,source.language,32]]);ranks.set(id,(id<=-2000000?-2000:0)+rank++);
   meta.languages[source.language]=(meta.languages[source.language]||0)+1;meta.counts[5]++;
  }
  meta.total=data.meta.total+Object.keys(sourceBooks).length;
  const query=new URL(location.href).searchParams;const selected=Number(query.get('category'));if(query.has('category')&&selected>=0&&selected<8)category=selected;
  applyLanguage();loadingState();
  const id=Number(query.get('book'));if(query.has('book'))readDeepLink(id);if(query.get('summary'))openSummary(query.get('summary'));
  $('catalog-retry').onclick=loadCatalog;window.addEventListener('online',loadCatalog);
  if('serviceWorker' in navigator)navigator.serviceWorker.register('/ketavilo/sw.js',{updateViaCache:'none'}).catch(()=>{});
  setTimeout(loadCatalog,100);
 }catch(error){
  $('status').textContent=t('partialError');$('grid').setAttribute('aria-busy','false');
  $('load-panel').hidden=false;$('load-message').textContent=t('partialError');$('catalog-static-link').textContent=t('readyCatalog');
  $('catalog-retry').hidden=false;$('catalog-retry').textContent=t('retryCatalog');$('catalog-retry').onclick=start;
 }
}

const categories={fa:['رمان و داستان','تاریخ و زندگی‌نامه','علوم و فناوری','فلسفه، روان‌شناسی و ادیان','کودکان و آموزش','ادبیات، شعر و هنر','سفر و جغرافیا','جامعه، سیاست و اقتصاد'],ps:['ناولونه او کیسې','تاریخ او ژوندلیک','ساینس او ټکنالوژي','فلسفه، ارواپوهنه او دینونه','ماشومان او زده‌کړه','ادب، شعر او هنر','سفر او جغرافیه','ټولنه، سیاست او اقتصاد'],en:['Fiction & stories','History & biography','Science & technology','Philosophy, psychology & religion','Children & education','Literature, poetry & arts','Travel & geography','Society, politics & economics']};
