const icons=['◇','◷','⌘','✦','⌂','❧','◎','▤'];
const storage={get(k,f){try{return JSON.parse(localStorage.getItem('openbook-'+k))??f}catch{return f}},set(k,v){try{localStorage.setItem('openbook-'+k,JSON.stringify(v));return true}catch{return false}}};
let language=storage.get('language',/^(fa|ps|en)/.exec(navigator.language)?.[1]||'fa');if(!text[language])language='fa';
