let view='library',sourceFilter='',category=-1,bookLanguage='',term='',sort='featured',limit=25,shelf='favorites',books=[],summaries=[],sourceBooks={},meta=null,localIds=new Set(),favorites=new Set(storage.get('favorites',[])),history=storage.get('history',[]),fontSize=storage.get('font',19),readerState=null,readerToken=0,toastTimer;
const featured=[1342,11,1661,84,2701,74,98,46,345,5200,1232,64317,174,1260,2600,1184,4300,768,1400,205,76];const ranks=new Map(featured.map((id,i)=>[id,i]));let byId=new Map();
const t=k=>text[language][k]||text.en[k]||k, n=value=>new Intl.NumberFormat(language).format(value);
const norm=value=>String(value).normalize('NFKD').replace(/[\u0300-\u036f\u064b-\u065f]/g,'').replace(/ي/g,'ی').replace(/ك/g,'ک').toLowerCase();
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2800)}
