function languageName(code){if(code==='und')return t('unknownLanguage');if(code==='fa')return language==='en'?'Persian':'فارسی';if(code==='ps')return language==='en'?'Pashto':'پښتو';try{return new Intl.DisplayNames([language],{type:'language'}).of(code)||code}catch{return code}}
function applyLanguage(){document.documentElement.lang=language;document.documentElement.dir=language==='en'?'ltr':'rtl';document.title='Ketavilo Library · '+t('library');$('ui-language').value=language;document.querySelectorAll('[data-t]').forEach(e=>e.textContent=t(e.dataset.t));document.querySelectorAll('[data-placeholder]').forEach(e=>e.placeholder=t(e.dataset.placeholder));document.querySelectorAll('[data-close]').forEach(e=>e.setAttribute('aria-label',t('closeLabel')));$('theme').setAttribute('aria-label',t('themeLabel'));$('headline').style.whiteSpace='pre-line';$('book-language').setAttribute('aria-label',t(view==='summaries'?'summaryLanguage':'bookLanguage'));$('book-language').closest('label').querySelector('span').textContent=t(view==='summaries'?'summaryLanguage':'bookLanguage');$('sort').setAttribute('aria-label',t('sort'));$('search').setAttribute('aria-label',t('search'));$('reader-body').style.fontSize=fontSize+'px';document.querySelectorAll('nav [data-view]').forEach(e=>e.setAttribute('aria-current',e.dataset.view===view?'page':'false'));$('view-title').textContent=t(view==='saved'?'shelf':view);if(meta){$('total').textContent=n(meta.total);$('category-count').textContent=n(8);$('summary-count').textContent=n(summaries.length);$('language-count').textContent=n(Object.keys(meta.languages).filter(x=>x!=='und').length)}buildLanguages();buildCategories();render()}
function buildLanguages(){const counts=view==='summaries'?fromEntries(['fa','ps','en'].map(code=>[code,summaries.filter(x=>x.content?Boolean(x.content[code]):Boolean(x[code])).length])):meta?.languages||{};let codes=view==='summaries'?['fa','ps','en']:Object.keys(counts).sort((a,b)=>counts[b]-counts[a]);codes=[...new Set(['fa','ps','en',...codes])];$('book-language').innerHTML=`<option value="">${esc(t('all'))}</option>`+codes.map(c=>`<option value="${esc(c)}">${esc(languageName(c))} · ${n(counts[c]||0)}</option>`).join('');$('book-language').value=bookLanguage}

function buildCategories(){$('categories').hidden=view!=='library';if(view!=='library')return;$('categories').innerHTML=categories[language].map((name,i)=>`<a href="/ketavilo/category-${i}.html" class="category ${category===i?'active':''}" data-category="${i}" aria-current="${category===i}"><span class="symbol" aria-hidden="true">${icons[i]}</span><span><b>${esc(name)}</b><small>${meta?n(availability?books.filter(b=>(b[4]&(1<<i))&&(availability==='pdf'?PDF_FILES[b[0]]:canRead(b[0]))).length:meta.counts[i]):'—'} ${t('items')}</small></span></a>`).join('')}
function cover(book){if(sourceBooks[book[0]])return `<small>GANJOOR · ${esc(t('collection'))}</small><strong dir="auto">${esc(book[1])}</strong><span aria-hidden="true">❧</span>`;return `<small>KETAVILO · ${book[0]}</small><strong dir="auto">${esc(book[1])}</strong><span aria-hidden="true">❧</span>`}
function bookCard(b){let saved=favorites.has(b[0]);return `<article class="card"><button class="save" data-save="${b[0]}" aria-pressed="${saved}" aria-label="${esc(t(saved?'unsave':'save'))}">${saved?'★':'☆'}</button><button class="cover" style="--cover:${colors[Math.abs(b[0])%colors.length]}" data-details="${b[0]}" aria-label="${esc(t('details')+': '+b[1])}">${cover(b)}</button><h3 dir="auto">${esc(b[1])}</h3><p class="author" dir="auto">${esc(b[2]||t('unknownAuthor'))}</p><div class="card-meta"><span>${esc(b[3].split('; ').map(languageName).join(' · '))}</span><span>${t(canRead(b[0])?'internalRead':'catalogOnly')}${PDF_FILES[b[0]]?' · PDF':''}</span></div><div class="card-actions"><button class="read-button" ${canRead(b[0])?`data-read="${b[0]}"`:'disabled'}>${t('read')}</button><button data-details="${b[0]}">${t('details')}</button>${pdfLink(b[0])}</div></article>`}
function setView(nextView){if(!['library','summaries','saved'].includes(nextView))return;view=nextView;limit=25;term='';$('search').value='';if(view==='summaries')bookLanguage='';applyLanguage();$('catalog').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
function filteredBooks(){let result=availability==='pdf'?books.filter(b=>PDF_FILES[b[0]]):availability==='readable'?books.filter(b=>canRead(b[0])):books;if(view==='library'&&sourceFilter)result=result.filter(b=>sourceFilter==='ganjoor'?Boolean(sourceBooks[b[0]]):!sourceBooks[b[0]]);if(view==='saved'){const ids=shelf==='favorites'?favorites:new Set(history.map(x=>x.id));result=result.filter(b=>ids.has(b[0]))}else if(category>=0)result=result.filter(b=>b[4]&(1<<category));if(bookLanguage)result=result.filter(b=>b[3].split('; ').includes(bookLanguage));const words=norm(term).split(/\s+/).filter(Boolean);if(words.length)result=result.filter(b=>words.every(w=>b.search.includes(w)));result=result.slice();if(view==='saved'&&shelf==='history'&&sort==='featured'){const order=new Map(history.map((x,i)=>[x.id,i]));result.sort((a,b)=>order.get(a[0])-order.get(b[0]))}else if(sort==='title')result.sort((a,b)=>a[1].localeCompare(b[1],language));else if(sort==='newest')result.sort((a,b)=>b[0]-a[0]);else result.sort((a,b)=>(ranks.get(a[0])??1e8)-(ranks.get(b[0])??1e8)||a[0]-b[0]);return result}
function render(){if(!meta)return;$('grid').setAttribute('aria-busy','false');$('shelf-tabs').hidden=view!=='saved';$('source-filter-label').hidden=view!=='library';$('availability').closest('label').hidden=view==='summaries';$('book-language').closest('label').hidden=false;$('sort').closest('label').hidden=view==='summaries';document.querySelectorAll('[data-shelf]').forEach(b=>b.classList.toggle('active',b.dataset.shelf===shelf));let results;if(view==='summaries'){const q=norm(term);results=summaries.filter(s=>(!bookLanguage||(s.content?Boolean(s.content[bookLanguage]):Boolean(s[bookLanguage])))&&(!q||norm([s.title.en,s.title.fa,s.title.ps,s.author].join(' ')).includes(q)));$('grid').innerHTML=results.slice(0,limit).map((s,i)=>`<article class="card"><button class="cover" style="--cover:${colors[i%8]}" data-summary="${s.key}" aria-label="${esc(t('summary')+': '+(s.title[language]||s.title.en))}"><small>KETAVILO · SUMMARY</small><strong dir="auto">${esc((s.title[language]||s.title.en))}</strong><span aria-hidden="true">❧</span></button><h3 dir="auto">${esc((s.title[language]||s.title.en))}</h3><p class="author" dir="auto">${esc(s.author)}</p><div class="card-meta"><span>${t(s.content?'sourcedSummary':'originalSummary')}</span><span>${s.content?esc(languageName(s.content[language]?language:'en')):t('summaryMinutes')}</span></div><div class="card-actions"><button class="read-button" data-summary="${s.key}">${t('summary')}</button></div></article>`).join('')}else{results=filteredBooks();$('grid').innerHTML=results.slice(0,limit).map(bookCard).join('')}
 const count=results.length;$('status').textContent=`${n(count)} ${t('results')}${view==='library'&&category>=0?' · '+categories[language][category]:''}`;if(view!=='summaries'&&!catalogLoaded&&sourceFilter!=='ganjoor')$('status').textContent=n(count)+' '+t('readyItems')+(category>=0?' · '+categories[language][category]:'');loadingState();$('shown').textContent=`${t('shown')} ${n(Math.min(count,limit))} ${t('of')} ${n(count)}`;$('more').hidden=count<=limit;$('empty').hidden=count>0;$('empty').querySelector('p').textContent=t(view==='saved'?'emptyShelf':view==='summaries'?'noSummaries':'emptyText');$('notice').hidden=false;$('notice').textContent=view==='summaries'?t('summaryNote'):bookLanguage&&!(meta.languages[bookLanguage]>0)?t('languageEmpty'):view==='library'?t('overlap'):t('localOnly');$('reset').disabled=availability==='readable'&&!term&&!bookLanguage&&category<0&&!sourceFilter;
}
function details(id){if(sourceBooks[id])return sourceDetails(id);const b=byId.get(id);if(!b)return;const tags=categories[language].filter((_,i)=>b[4]&(1<<i));$('details-content').innerHTML=`<div class="details-layout"><div class="cover" style="--cover:${colors[Math.abs(id)%8]}">${cover(b)}</div><div><h2 dir="auto">${esc(b[1])}</h2><p><b>${t('author')}:</b> <span dir="auto">${esc(b[2]||t('unknownAuthor'))}</span></p><p>${t('language')}: ${esc(b[3].split('; ').map(languageName).join(' · '))}</p><p>${t('id')}: ${id}</p><div class="tags">${tags.map(tag=>`<span>${esc(tag)}</span>`).join('')}</div></div></div><div class="detail-actions">${pdfLink(id)}<button class="primary" ${canRead(id)?`data-read="${id}"`:'disabled'}>${t('read')}</button><a href="https://www.gutenberg.org/ebooks/${id}.epub3.images">${t('download')}</a><a href="${localIds.has(id)?'/ketavilo/'+id+'.txt':'https://www.gutenberg.org/ebooks/'+id+'.txt.utf-8'}" ${localIds.has(id)?'download':''} target="_blank" rel="noopener noreferrer">${t('downloadTxt')}</a><button data-save="${id}" aria-pressed="${favorites.has(id)}">${t(favorites.has(id)?'unsave':'save')}</button><button data-share="${id}">${t('share')}</button></div><p class="source-note"><a href="https://www.gutenberg.org/ebooks/${id}" target="_blank" rel="noopener noreferrer">${t('source')}</a><br>${t('rights')}</p>`;$('details').showModal()}
function toggleFavorite(id){if(favorites.has(id)){favorites.delete(id);toast(t('removed'))}else{favorites.add(id);toast(t('saved'))}save('favorites',[...favorites]);render();if($('details').open){$('details').close();details(id)}}
function remember(id,page=0){history=history.filter(x=>x.id!==id);history.unshift({id,page,time:Date.now()});history=history.slice(0,100);save('history',history)}
function splitPages(content){const paragraphs=content.replace(/\r\n/g,'\n').split(/\n\s*\n/);const pages=[];let page='';for(let paragraph of paragraphs){while(paragraph.length>6500){if(page){pages.push(page);page=''}pages.push(paragraph.slice(0,6500));paragraph=paragraph.slice(6500)}if(page.length+paragraph.length>6500&&page){pages.push(page);page=''}page+=paragraph+'\n\n'}if(page)pages.push(page);return pages}
async function readBook(id){if(sourceBooks[id]&&!localIds.has(id))return readSourceBook(id);const b=byId.get(id);if(!b)return;if($('details').open)$('details').close();if($('summary-dialog').open)$('summary-dialog').close();const token=++readerToken;$('reader-title').textContent=b[1];$('reader-title').dir='auto';$('reader-status').textContent=t('readerLoading');$('reader-body').replaceChildren();$('reader-body').className='';$('reader-body').dir=/^(fa|ps|ar|he)/.test(b[3])?'rtl':'ltr';$('reader-links').innerHTML=pdfLink(id)+`<a href="https://www.gutenberg.org/ebooks/${id}" target="_blank" rel="noopener noreferrer">${t('source')}</a><a href="https://www.gutenberg.org/ebooks/${id}.epub3.images">${t('download')}</a>`;if(sourceBooks[id])$('reader-links').innerHTML=pdfLink(id);const local=localIds.has(id);$('font-tools').hidden=!local;$('reader-pages').hidden=!local;if(!$('reader').open)$('reader').showModal();if(local){try{const content=await fetchData(id+'.txt',15000,'text');if(token!==readerToken||!$('reader').open)return;const pages=splitPages(content);const previous=history.find(x=>x.id===id)?.page||0;readerState={id,pages,page:Math.min(previous,pages.length-1)};$('reader-status').textContent='';showPage()}catch(e){if(token===readerToken){$('reader-status').textContent=t('readerError');$('reader-body').innerHTML=`<button data-read="${id}">${t('readerRetry')}</button>`}}}else{displayRemoteText(id,b,token)}}
function showPage(){if(!readerState)return;const {id,pages,page}=readerState;$('reader-body').textContent=pages[page];$('reader-body').scrollTop=0;$('reader-body').style.fontSize=fontSize+'px';$('page-position').textContent=`${t('page')} ${n(page+1)} ${t('of')} ${n(pages.length)}`;$('previous').disabled=page===0;$('next').disabled=page===pages.length-1;remember(id,page)}
function openSummary(key){const sourceSummary=summaries.find(x=>x.key===key);if(sourceSummary?.content)return openSourcedSummary(sourceSummary);const s=summaries.find(x=>x.key===key);if(!s)return;const c=s[language];$('summary-body').innerHTML=`<h2>${esc((s.title[language]||s.title.en))}</h2><p class="author" dir="auto">${esc(s.author)}</p><p class="summary-lead">${esc(c.lead)}</p><div class="summary-section"><h3>${t('keyIdeas')}</h3><ul>${c.ideas.map(idea=>`<li>${esc(idea)}</li>`).join('')}</ul><h3>${t('reflection')}</h3><p>${esc(c.reflection)}</p><p class="source-note">${t('summaryDisclaimer')}</p>${s.id?`<button class="primary" data-read="${s.id}">${t('read')}</button>`:''}</div>`;$('summary-dialog').showModal()}
document.addEventListener('click',async e=>{const button=e.target.closest('button, a[data-category], a[data-view], a[data-read]');if(!button)return;if(!meta&&button.tagName==='A')return;if(button.dataset.view){e.preventDefault();setView(button.dataset.view);}if(button.dataset.category!==undefined){e.preventDefault();const selected=Number(button.dataset.category);category=category===selected?-1:selected;limit=25;buildCategories();render()}if(button.dataset.save)toggleFavorite(Number(button.dataset.save));if(button.dataset.details)details(Number(button.dataset.details));if(button.dataset.read){e.preventDefault();readBook(Number(button.dataset.read));}if(button.dataset.summary)openSummary(button.dataset.summary);if(button.dataset.close)$(button.dataset.close).close();if(button.dataset.shelf){shelf=button.dataset.shelf;limit=25;render()}if(button.dataset.share){try{const url=location.origin+'/ketavilo/?v=9&book='+encodeURIComponent(button.dataset.share);await navigator.clipboard.writeText(url);toast(t('copied'))}catch{toast(t('copyFail'))}}});
prepareControls();
$('theme').onclick=()=>{theme=theme==='light'?'dark':'light';document.body.classList.toggle('light',theme==='light');save('theme',theme)};$('ui-language').onchange=e=>{language=e.target.value;save('language',language);applyLanguage()};let searchTimer;$('search').oninput=e=>{term=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{limit=25;render()},180)};$('book-language').onchange=e=>{bookLanguage=e.target.value;limit=25;render()};$('sort').onchange=e=>{sort=e.target.value;limit=25;render()};$('more').onclick=()=>{limit+=25;render()};$('source-filter').onchange=e=>{sourceFilter=e.target.value;limit=25;render()};$('reset').onclick=()=>{availability='readable';if($('availability'))$('availability').value=availability;sourceFilter='';$('source-filter').value='';term='';bookLanguage='';category=-1;limit=25;$('search').value='';$('book-language').value='';buildCategories();render()};$('about-button').onclick=()=>$('help-dialog').showModal();$('previous').onclick=()=>{if(readerState&&readerState.page>0){readerState.page--;showPage()}};$('next').onclick=()=>{if(readerState&&readerState.page<readerState.pages.length-1){readerState.page++;showPage()}};for(const [id,delta] of [['font-smaller',-1],['font-larger',1]])$(id).onclick=()=>{fontSize=Math.max(15,Math.min(28,fontSize+delta));$('reader-body').style.fontSize=fontSize+'px';save('font',fontSize)};
$('reader').addEventListener('close',()=>{readerToken++;$('reader-body').replaceChildren();readerState=null;if(view==='saved')render()});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('search').focus();$('catalog').scrollIntoView()}});
document.body.classList.toggle('light',theme==='light');applyLanguage();
function sourceDetails(id){const source=sourceBooks[id];$('details-content').innerHTML=`<h2 dir="auto">${esc(source.title)}</h2><p dir="auto">${esc(source.author)}</p><p>${esc(t('collection'))} · ${esc(languageName(source.language))} · ${esc(source.sourceName)}</p>${source.language==='und'?`<p class="notice">${t('unknownLanguageNote')}</p>`:''}<div class="detail-actions">${pdfLink(id)}<button class="primary" ${canRead(id)?`data-read="${id}"`:'disabled'}>${t('read')}</button><a href="${esc(source.download)}" target="_blank" rel="noopener noreferrer">${t('download')}</a><button data-save="${id}">${t(favorites.has(id)?'unsave':'save')}</button><button data-share="${id}">${t('share')}</button></div><p class="source-note">${t('rightsSource')}</p><a href="${esc(source.source)}" target="_blank" rel="noopener noreferrer">${t('source')}</a>`;$('details').showModal()}
function readSourceBook(id){return showGanjoorSection(id,new URL(sourceBooks[id].source).pathname.replace(/\/$/,''),'category')}
